using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Handles a pending join request in a chat
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> ProcessChatJoinRequestAsync(long chatId = default, long userId = default, bool approve = default)
    {

           using var activity =  StartCallActivity("ProcessChatJoinRequestAsync", typeof(ProcessChatJoinRequest).FullName ?? "ProcessChatJoinRequestAsync");

           try
           {
             return client.ProcessChatJoinRequestAsync(chatId, userId, approve);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
